effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float d;
  if (mode <= 0) d = 1.0 - gmLum(c);
  else if (mode <= 1) d = 1.0 - uv.y;
  else d = length(uv - 0.5) * 2.0;
  float f = clamp((d - near) * density, 0.0, 1.0) * mixAmt;
  vec3 col = mix(c, fogColor.rgb, f);
  gl_FragColor = vec4(col * a, a);
}
